5\u043d\u0438\u0442\u044c \u0440\u0430\u0437\u043c\u0435\u0440 \u044d\u0444\u0444\u0435\u043a\u0442\u0430 \u0441 \u0434\u043e\u0432\u0435\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u0430\u043c\u0438 \u0438 \u043e\u0431\u044a\u044f\u0441\u043d\u0438\u0442\u044c \u041c\u0415\u0425\u0410\u041d\u0418\u0417\u041c \u0440\u0430\u0437\u043d\u0438\u0446\u044b (\u0431\u043e\u043b\u044c\u0448\u0435 LLM-\u0432\u044b\u0437\u043e\u0432\u043e\u0432 / \u0431\u043e\u043b\u044c\u0448\u0435 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0445 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 / \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u0435\u0435 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u043d\u0430 \u0442\u043e\u043a\u0435\u043d), \u0430 \u043d\u0435 \u043f\u0440\u043e\u0441\u0442\u043e \u043a\u043e\u043d\u0441\u0442\u0430\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u00ab\u043c\u0435\u0434\u043b\u0435\u043d\u043d\u0435\u0435\u00bb. \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u0447\u0435\u0441\u0442\u043d\u043e\u0433\u043e \u0437\u0430\u043c\u0435\u0440\u0430 \u0441 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u043e\u0439; \u041d\u0415 \u0437\u0430\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043f\u0440\u043e\u0432\u0435\u0434\u0451\u043d.\n\n## 2. \u041c\u0435\u0442\u0440\u0438\u043a\u0438\n\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430:\n- end-to-end per-query wall-clock \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u044c: \u043e\u0442 \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u043f\u043e\u0434\u0430\u0447\u0438 \u0437\u0430\u0434\u0430\u0447\u0438 (\u0441\u044b\u0440\u043e\u0433\u043e \u0442\u0435\u043a\u0441\u0442\u0430) \u0432 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u043c\u0435\u0442\u043e\u0434\u0430 \u0434\u043e \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043e\u0442\u0432\u0435\u0442\u0430; \u043c\u0435\u0434\u0438\u0430\u043d\u0430 \u043f\u043e N \u043f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u0438\u044f\u043c \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443 (\u043c\u0435\u0434\u0438\u0430\u043d\u0430 \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u0430 \u043a \u0432\u044b\u0431\u0440\u043e\u0441\u0430\u043c \u0441\u0435\u0442\u0438/\u043e\u0447\u0435\u0440\u0435\u0434\u0438); \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u043c \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u0434\u043b\u044f \u0440\u043e\u0431\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438.\n\n\u0412\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0435 (\u043e\u0431\u044a\u044f\u0441\u043d\u044f\u044e\u0449\u0438\u0435) \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u2014 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b \u0434\u043b\u044f \u0440\u0430\u0437\u0431\u043e\u0440\u0430 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u0430:\n- \u0447\u0438\u0441\u043b\u043e LLM-\u0432\u044b\u0437\u043e\u0432\u043e\u0432 \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443 (\u0434\u043b\u044f Expert/PAL = 1, \u0434\u043b\u044f BoT = 3 \u0433\u0435\u043d-\u0432\u044b\u0437\u043e\u0432\u0430 + 1 \u043d\u0435\u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0439 retrieval);\n- \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0435 \u0442\u043e\u043a\u0435\u043d\u044b \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443 (prompt + completion) \u0441 \u0440\u0430\u0437\u0431\u0438\u0432\u043a\u043e\u0439 \u043f\u043e \u044d\u0442\u0430\u043f\u0430\u043c: BoT \u2014 distillation / retrieval / instance-reasoning / router; PAL \u2014 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u043a\u043e\u0434\u0430; Expert \u2014 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f;\n- \u0442\u043e\u043a\u0435\u043d\u044b/\u0441\u0435\u043a (completion-\u0442\u043e\u043a\u0435\u043d\u044b \u00f7 \u0432\u0440\u0435\u043c\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438) \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u044c \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438 \u043d\u0430 \u0442\u043e\u043a\u0435\u043d \u043d\u0435 \u043e\u0442\u043b\u0438\u0447\u0430\u0435\u0442\u0441\u044f \u043c\u0435\u0436\u0434\u0443 \u043c\u0435\u0442\u043e\u0434\u0430\u043c\u0438 (\u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u0431\u044d\u043a\u0435\u043d\u0434\u0435 \u0434\u043e\u043b\u0436\u043d\u0430 \u0431\u044b\u0442\u044c \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0439; \u044d\u0442\u043e \u0430\u0442\u0440\u0438\u0431\u0443\u0446\u0438\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u044b);\n- \u0432\u0440\u0435\u043c\u044f retrieval (\u043d\u0435\u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u043e\u0435, \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433-\u043c\u043e\u0434\u0435\u043b\u044c) \u0438 \u0432\u0440\u0435\u043c\u044f \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u043a\u043e\u0434\u0430 \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u043c\u0438 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430\u043c\u0438 \u0432 breakdown.\n- (\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e, \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f API) time-to-first-token \u0434\u043b\u044f \u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u0441\u0435\u0442\u0435\u0432\u043e\u0439/\u043e\u0447\u0435\u0440\u0435\u0434\u043d\u043e\u0439 \u0437\u0430\u0434\u0435\u0440\u0436\u043a\u0438 \u043e\u0442 \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u0438 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438.\n\nBreakdown \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d: \u0438\u0442\u043e\u0433\u043e\u0432\u0430\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u0430 BoT\u2212Expert \u0440\u0430\u0441\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043d\u0430 (\u0430) \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0441\u0435\u0442\u0435\u0432\u044b\u0435/\u043e\u0447\u0435\u0440\u0435\u0434\u043d\u044b\u0435 \u0437\u0430\u0434\u0435\u0440\u0436\u043a\u0438 \u043e\u0442 \u0434\u0432\u0443\u0445 \u0434\u043e\u043f. LLM-\u0432\u044b\u0437\u043e\u0432\u043e\u0432, (\u0431) \u0442\u043e\u043a\u0435\u043d\u044b, \u0441\u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0432 distillation/instance-reasoning/router, (\u0432) \u0432\u0440\u0435\u043c\u044f \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433-retrieval, (\u0433) (\u0435\u0441\u043b\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f) \u0434\u043e\u043f. \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043a\u043e\u0434\u0430, (\u0434) \u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u0443\u044e \u0440\u0430\u0437\u043d\u0438\u0446\u0443 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438 \u043d\u0430 \u0442\u043e\u043a\u0435\u043d (\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e \u2248 0). \u042d\u0442\u043e \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u00abBoT \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u0435\u0435\u00bb \u0432 \u043e\u0431\u044a\u044f\u0441\u043d\u0435\u043d\u0438\u0435 \u00ab\u043d\u0430 \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043e\u0432 \u0438 \u0437\u0430 \u0441\u0447\u0451\u0442 \u0447\u0435\u0433\u043e\u00bb.\n\n## 3. \u041a\u0430\u043a \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u00abinference time\u00bb\n- \u041f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u0435/\u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u043c\u0435\u0442\u0430-\u0431\u0443\u0444\u0435\u0440\u0430 BoT (Buffer Manager, \u0434\u0438\u0441\u0442\u0438\u043b\u043b\u044f\u0446\u0438\u044f \u0448\u0430\u0431\u043b\u043e\u043d\u043e\u0432, seed-\u0448\u0430\u0431\u043b\u043e\u043d\u044b) \u2014 \u041e\u0414\u041d\u041e\u0420\u0410\u0417\u041e\u0412\u0410\u042f \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u0430\u044f \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c. \u0412 per-query \u0432\u0440\u0435\u043c\u044f \u041d\u0415 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f; \u043e\u0442\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e (\u043e\u0434\u043d\u0430 \u0446\u0438\u0444\u0440\u0430 \u00abtime-to-build buffer\u00bb \u0441 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0435\u0439 \u0431\u0443\u0444\u0435\u0440\u0430: \u0447\u0438\u0441\u043b\u043e \u0448\u0430\u0431\u043b\u043e\u043d\u043e\u0432, k retrieval).\n- Template Retrieval \u2014 \u0412\u041a\u041b\u042e\u0427\u0410\u0415\u0422\u0421\u042f \u0432 per-query (\u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u043a\u0430\u0436\u0434\u044b\u0439 \u0437\u0430\u043f\u0440\u043e\u0441), \u043d\u043e \u0432 breakdown \u043f\u043e\u043a\u0430\u0437\u0430\u043d \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043a\u0430\u043a \u043d\u0435\u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430.\n- \u0418\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043a\u043e\u0434\u0430 (PAL; \u043a\u043e\u0434\u0438\u043d\u0433-\u043f\u0443\u0442\u044c BoT) \u2014 \u0412\u041a\u041b\u042e\u0427\u0410\u0415\u0422\u0421\u042f \u0432 end-to-end (\u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u043e\u0442\u0432\u0435\u0442 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044e), \u0432 breakdown \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043a\u0430\u043a \u043d\u0435-LLM \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430.\n- \u0418\u0442\u043e\u0433\u043e\u0432\u0430\u044f \u0442\u0440\u0430\u043a\u0442\u043e\u0432\u043a\u0430: primary inference time = \u0441\u0442\u0435\u043d\u043d\u044b\u0435 \u0447\u0430\u0441\u044b \u0434\u043e \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043e\u0442\u0432\u0435\u0442\u0430; \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u043e\u0442\u0447\u0451\u0442 \u2014 \u0447\u0438\u0441\u0442\u0430\u044f LLM-\u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u0438 \u0435\u0451 \u0442\u043e\u043a\u0435\u043d\u044b/\u0441\u0435\u043a.\n\n## 4. \u041c\u0435\u0442\u043e\u0434\u044b (\u043a\u0430\u043a \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u044e\u0442\u0441\u044f; \u0447\u0442\u043e \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u0442\u044c)\n- Expert (single-query, \u0438\u0437 \u0422\u0417): 1 LLM-\u0432\u044b\u0437\u043e\u0432 \u0441 \u044d\u043a\u0441\u043f\u0435\u0440\u0442\u043d\u043e \u0441\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u043c \u043f\u043e\u0434 \u0437\u0430\u0434\u0430\u0447\u0443 (\u0441 few-shot \u043f\u0440\u0438\u043c\u0435\u0440\u0430\u043c\u0438), 1 \u043e\u0442\u0432\u0435\u0442.\n- PAL (single-query, \u0438\u0437 \u0422\u0417): 1 LLM-\u0432\u044b\u0437\u043e\u0432 \u2014 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f Python-\u043a\u043e\u0434\u0430; \u0437\u0430\u0442\u0435\u043c \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0432 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 (subprocess/\u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440) \u2192 \u043e\u0442\u0432\u0435\u0442. End-to-end \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044e + exec.\n- BoT (retrieval-augmented, \u0438\u0437 \u0422\u0417): 3 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0445 LLM-\u0432\u044b\u0437\u043e\u0432\u0430 \u2014 (1) Problem Distillation (\u0437\u0430\u0434\u0430\u0447\u0430 \u2192 distilled problem), (2) Instance Reasoning (retrieved template + distilled problem \u2192 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0435; \u0434\u043b\u044f \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u0434\u0430\u0447 \u2014 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u043a\u043e\u0434\u0430 + \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435), (3) Router/\u043c\u0435\u0442\u0430-\u0440\u0438\u0437\u043e\u043d\u0435\u0440 (\u0432\u044b\u0431\u043e\u0440 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043e\u0442\u0432\u0435\u0442\u0430 \u0438\u0437 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u0432); + 1 \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433-retrieval top-k \u0448\u0430\u0431\u043b\u043e\u043d\u043e\u0432 \u0438\u0437 \u043c\u0435\u0442\u0430-\u0431\u0443\u0444\u0435\u0440\u0430. \u0411\u0443\u0444\u0435\u0440 \u043f\u0440\u0435\u0434-\u0441\u043e\u0431\u0440\u0430\u043d (\u0441\u043c. \u043f.3).\n- \u0412\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0432 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u043c \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 \u0430\u0432\u0442\u043e\u0440\u043e\u0432 (github.com/dylandil/Buffer-of-Thoughts): \u0442\u043e\u0447\u043d\u044b\u0435 \u043f\u0440\u043e\u043c\u043f\u0442\u044b \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0448\u0430\u0433\u0430, \u0444\u043e\u0440\u043c\u0430\u0442 \u0448\u0430\u0431\u043b\u043e\u043d\u043e\u0432, \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433-\u043c\u043e\u0434\u0435\u043b\u044c \u0438 k retrieval, \u043d\u0430\u043b\u0438\u0447\u0438\u0435/\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c router'\u0430 \u043d\u0430 \u043a\u0430\u0436\u0434\u044b\u0439 \u0437\u0430\u043f\u0440\u043e\u0441, \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u043a\u043e\u0434\u0438\u043d\u0433-\u043f\u0443\u0442\u0438 \u0438 exec; \u0441\u0432\u0435\u0440\u0438\u0442\u044c \u0421\u041b\u0415\u0414 \u043d\u0430\u0448\u0435\u0433\u043e \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430 \u0441 \u0442\u0440\u0430\u0441\u0441\u043e\u0439 \u0440\u0435\u043f\u043e (\u0447\u0438\u0441\u043b\u043e \u0432\u044b\u0437\u043e\u0432\u043e\u0432/\u044d\u0442\u0430\u043f\u043e\u0432 \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443). \u041f\u043e\u043a\u0430 \u043d\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u2014 \u044d\u0442\u043e \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f, \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u043d\u044b\u0435 \u043d\u0438\u0436\u0435.\n\n## 5. \u0411\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0438, \u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u0438 \u0431\u044e\u0434\u0436\u0435\u0442 (\u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430)\n\u0420\u0430\u0437\u043c\u0435\u0440\u044b \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432 (\u0440\u0430\u0431\u043e\u0447\u0438\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043f\u043e \u043f\u0430\u043c\u044f\u0442\u0438 \u043e \u0441\u0442\u0430\u0442\u044c\u0435, \u043a \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u043f\u043e \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u043c \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430\u043c):\n- Game of 24: 1 364 \u0437\u0430\u0434\u0430\u0447\u0438 (4 \u0447\u0438\u0441\u043b\u0430, \u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438, \u0446\u0435\u043b\u044c 24; \u043c\u0435\u0442\u0440\u0438\u043a\u0430 accuracy).\n- MGSM: 250 \u0437\u0430\u0434\u0430\u0447/\u044f\u0437\u044b\u043a; \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u043c 5 \u044f\u0437\u044b\u043a\u043e\u0432 (en, zh, es, fr, de), \u0442.\u0435. 1 250 \u0437\u0430\u0434\u0430\u0447; \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 \u0434\u043e \u0432\u0441\u0435\u0445 10 \u044f\u0437\u044b\u043a\u043e\u0432 \u2014 \u0444\u043b\u0430\u0433 \u00abextra\u00bb, \u0435\u0441\u043b\u0438 \u0431\u044e\u0434\u0436\u0435\u0442 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442; \u044f\u0437\u044b\u043a \u0437\u0430\u0434\u0430\u0447\u0438 \u0442\u043e\u0442 \u0436\u0435 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0442\u0440\u0451\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432.\n- Checkmate-in-One: ~1 105 \u0437\u0430\u0434\u0430\u0447 \u00ab\u043d\u0430\u0439\u0442\u0438 \u043c\u0430\u0442 \u0432 \u043e\u0434\u0438\u043d \u0445\u043e\u0434\u00bb (\u0440\u0430\u0437\u043c\u0435\u0440/\u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u2014 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435, \u043a \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438).\n\n\u0421\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u044f \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438 (\u0434\u0432\u0430 \u0442\u0440\u0435\u043a\u0430):\n- TIMING (\u043f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 N=5 \u043f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u0438\u0439 \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443 \u0443 \u0432\u0441\u0435\u0445 \u0442\u0440\u0451\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432): \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u0430\u044f \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0430 S \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0441\u0438\u0434\u043e\u043c: Game of 24 \u2014 500; MGSM \u2014 5\u00d7200 = 1 000 (\u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e \u043f\u043e \u044f\u0437\u044b\u043a\u0430\u043c); Checkmate-in-One \u2014 500. \u0418\u0442\u043e\u0433\u043e S = 2 000 \u0437\u0430\u0434\u0430\u0447. \u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435 N=5: \u043f\u0440\u0438 \u043f\u0430\u0440\u043d\u043e\u043c \u0434\u0438\u0437\u0430\u0439\u043d\u0435 (\u043e\u0434\u043d\u0438 \u0438 \u0442\u0435 \u0436\u0435 \u0437\u0430\u0434\u0430\u0447\u0438 \u0443 \u0442\u0440\u0451\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432) \u0438 2 000 \u043f\u0430\u0440 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u0432\u044b\u0441\u043e\u043a\u0430; N=5 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u043b\u044f \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0439 \u043c\u0435\u0434\u0438\u0430\u043d\u044b \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438; \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 N \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443 \u0434\u0430\u0451\u0442 \u0441\u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c. \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u2014 \u043f\u0435\u0440\u0435\u0441\u0447\u0451\u0442 \u043f\u0440\u0438 N=3.\n- ACCURACY (sanity-check \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438, \u043e\u0434\u0438\u043d \u043f\u0440\u043e\u0445\u043e\u0434 temp=0 \u043d\u0430 \u043f\u043e\u043b\u043d\u043e\u043c \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0435): Game of 24 1 364; MGSM 5 \u044f\u0437\u044b\u043a\u043e\u0432 1 250 (\u0438\u043b\u0438 10 \u044f\u0437\u044b\u043a\u043e\u0432 2 500); Checkmate ~1 105.\n\n\u0427\u0438\u0441\u043b\u043e LLM-\u0432\u044b\u0437\u043e\u0432\u043e\u0432:\n- Timing: S\u00d75 \u0432\u044b\u0437\u043e\u0432\u043e\u0432/\u0437\u0430\u0434\u0430\u0447\u0430\u00d7N=5 = 2 000\u00d725 = 50 000 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0445 LLM-\u0432\u044b\u0437\u043e\u0432\u043e\u0432 + 10 000 \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433-retrieval (BoT: 2 000\u00d75) + \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043a\u043e\u0434\u0430 \u0434\u043b\u044f PAL \u0438 \u043a\u043e\u0434\u0438\u043d\u0433-\u043f\u0443\u0442\u0438 BoT \u043d\u0430 Game of 24 \u0438 MGSM (~7 500 \u043a\u0430\u0436\u0434\u043e\u0439 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0438; \u0434\u043b\u044f Checkmate \u043a\u043e\u0434\u0438\u043d\u0433-\u043f\u0443\u0442\u044c \u043e\u0431\u044b\u0447\u043d\u043e \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u2014 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u0440\u0435\u043f\u043e).\n- Accuracy: (1 364+1 250+1 105)\u00d75 \u2248 18 600 (\u0438\u043b\u0438 ~24 800 \u043f\u0440\u0438 10 \u044f\u0437\u044b\u043a\u0430\u0445 MGSM).\n- \u0418\u0442\u043e\u0433\u043e \u2248 70\u201375 \u0442\u044b\u0441. LLM-\u0432\u044b\u0437\u043e\u0432\u043e\u0432 + ~10 \u0442\u044b\u0441. \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433\u043e\u0432 + ~15\u201325 \u0442\u044b\u0441. exec \u043f\u0440\u0438 ~1\u20131,5 \u0442\u044b\u0441. \u0442\u043e\u043a\u0435\u043d\u043e\u0432/\u0432\u044b\u0437\u043e\u0432 \u2248 90\u2013110 \u043c\u043b\u043d \u0442\u043e\u043a\u0435\u043d\u043e\u0432 (\u043e\u0446\u0435\u043d\u043a\u0430, \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u0432/\u0434\u043b\u0438\u043d).\n\n## 6. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\n- \u041e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 LLM-\u0431\u044d\u043a\u0435\u043d\u0434 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0442\u0440\u0451\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 (\u0442\u0430 \u0436\u0435 \u043c\u043e\u0434\u0435\u043b\u044c/\u0447\u0435\u043a\u043f\u043e\u0439\u043d\u0442/\u0432\u0435\u0440\u0441\u0438\u044f/\u043a\u0432\u0430\u043d\u0442\u0438\u0437\u0430\u0446\u0438\u044f, batch=1, \u0431\u0435\u0437 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438; \u043f\u0440\u0435\u0434\u043f\u043e\u0447\u0442\u0438\u0442\u0435\u043b\u0435\u043d \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0439 \u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441).\n- \u041e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u0434\u0435\u043a\u043e\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f: seed \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d, temperature=0 (greedy), top_p \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u043d\u0435\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u044e\u0449\u0438\u0439 max_tokens \u0443 \u0432\u0441\u0435\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 (per-\u044d\u0442\u0430\u043f\u043d\u044b\u0435 \u043b\u0438\u043c\u0438\u0442\u044b BoT \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u044b \u0431\u044b\u0442\u044c \u0441\u0432\u044f\u0437\u044b\u0432\u0430\u044e\u0449\u0438\u043c\u0438 \u043f\u0440\u0438 \u0437\u0430\u043c\u0435\u0440\u0435), \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0430\u044f \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043a\u044d\u0448\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u0432.\n- \u041e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0441\u044b\u0440\u043e\u0439 \u0442\u0435\u043a\u0441\u0442 \u0437\u0430\u0434\u0430\u0447\u0438 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432; \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u043c\u043f\u0442\u044b.\n- Warm-up: ~20 \u00ab\u043f\u0443\u0441\u0442\u044b\u0445\u00bb \u0437\u0430\u043f\u0440\u043e\u0441\u043e\u0432 \u043f\u0435\u0440\u0435\u0434 \u043a\u0430\u0436\u0434\u044b\u043c \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u043e\u043c, \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u0440\u0435\u0432 \u043f\u043e\u0441\u043b\u0435 \u043f\u0430\u0443\u0437; \u041f\u0415\u0420\u0412\u042b\u0419 \u0437\u0430\u043f\u0440\u043e\u0441 \u043a\u0430\u0436\u0434\u043e\u0439 \u0441\u0435\u0441\u0441\u0438\u0438/\u043c\u0435\u0442\u043e\u0434\u0430 \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f (\u043a\u044d\u0448/\u0432\u044b\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043f\u0430\u043c\u044f\u0442\u0438).\n- \u0418\u043d\u0442\u0435\u0440\u043b\u0438\u0432\u0438\u043d\u0433 \u043f\u0440\u043e\u0442\u0438\u0432 \u0434\u0440\u0435\u0439\u0444\u0430: \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u043c\u0435\u0442\u043e\u0434\u043e\u0432 \u0438 \u0437\u0430\u0434\u0430\u0447 \u0440\u0430\u043d\u0434\u043e\u043c\u0438\u0437\u0438\u0440\u0443\u0435\u0442\u0441\u044f (\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 seed), \u043c\u0435\u0442\u043e\u0434\u044b \u0447\u0435\u0440\u0435\u0434\u0443\u044e\u0442\u0441\u044f \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u0439 \u0437\u0430\u0434\u0430\u0447\u0435; \u0434\u043b\u044f MGSM \u044f\u0437\u044b\u043a\u0438 \u0447\u0435\u0440\u0435\u0434\u0443\u044e\u0442\u0441\u044f \u0441\u0442\u0440\u0430\u0442\u0430\u043c\u0438.\n- \u0421\u0432\u0435\u0440\u043a\u0430 accuracy \u0441 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c\u0438 (\u0434\u043e\u043f\u0443\u0441\u043a \u00b12\u20133 \u043f.\u043f. \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0443) \u043a\u0430\u043a sanity-check \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438; \u043f\u0440\u0438 \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0438 \u2014 \u0447\u0438\u043d\u0438\u0442\u044c \u043f\u0440\u043e\u043c\u043f\u0442\u044b/\u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u0414\u041e \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u0442\u0430\u0439\u043c\u0438\u043d\u0433\u0430.\n- \u0422\u0435\u043b\u0435\u043c\u0435\u0442\u0440\u0438\u044f \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f: \u0443\u0442\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u044f GPU, batch=1, \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u043d\u044b\u0445 \u0437\u0430\u043f\u0440\u043e\u0441\u043e\u0432, \u043f\u0440\u0438 API \u2014 ping/\u0437\u0430\u0434\u0435\u0440\u0436\u043a\u0430 \u0441\u0435\u0442\u0438.\n\n## 7. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430 (\u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430)\n\u041d\u0430 \u043a\u0430\u0436\u0434\u043e\u0439 \u0437\u0430\u0434\u0430\u0447\u0435: \u043c\u0435\u0434\u0438\u0430\u043d\u0430 \u043f\u043e N=5 \u043f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u0438\u044f\u043c = per-problem \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u044c \u043c\u0435\u0442\u043e\u0434\u0430; \u0442\u043e \u0436\u0435 \u0434\u043b\u044f per-stage \u0440\u0430\u0437\u0431\u0438\u0432\u043a\u0438.\n\u041f\u0430\u0440\u043d\u043e\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u043e \u043e\u0434\u043d\u0438\u043c \u0438 \u0442\u0435\u043c \u0436\u0435 \u0437\u0430\u0434\u0430\u0447\u0430\u043c (H0: \u0440\u0430\u0437\u043d\u0438\u0446\u0430 = 0):\n- Wilcoxon signed-rank \u043f\u043e per-problem \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044f\u043c;\n- \u043f\u0430\u0440\u043d\u044b\u0439 t-\u0442\u0435\u0441\u0442 \u043d\u0430 log-\u0432\u0440\u0435\u043c\u0435\u043d\u0438 (\u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442 H0: \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u0433\u0435\u043e\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0441\u0440\u0435\u0434\u043d\u0438\u0445 = 1);\n- \u0440\u0430\u0437\u043c\u0435\u0440 \u044d\u0444\u0444\u0435\u043a\u0442\u0430 = \u043c\u0435\u0434\u0438\u0430\u043d\u043d\u043e\u0435 \u043f\u043e \u0437\u0430\u0434\u0430\u0447\u0430\u043c \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 lat(BoT)/lat(Expert) \u0438 lat(BoT)/lat(PAL), \u043f\u043b\u044e\u0441 \u0433\u0435\u043e\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435;\n- bootstrap-95% CI \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f: \u0440\u0435\u0441\u0435\u043c\u043f\u043b\u0438\u043d\u0433 \u0437\u0430\u0434\u0430\u0447 (\u0438\u043d\u0434\u0435\u043a\u0441 \u0437\u0430\u0434\u0430\u0447\u0438 \u0440\u0435\u0441\u0435\u043c\u043f\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0446\u0435\u043b\u0438\u043a\u043e\u043c, \u0447\u0442\u043e\u0431\u044b \u0432\u0440\u0435\u043c\u0435\u043d\u0430 \u0442\u0440\u0451\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 \u043e\u0434\u043d\u043e\u0439 \u0437\u0430\u0434\u0430\u0447\u0438 \u043e\u0441\u0442\u0430\u0432\u0430\u043b\u0438\u0441\u044c \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u043c\u0438), \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u043e \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0443.\n\u041c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f: 3 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430 \u00d7 2 \u043f\u0430\u0440\u044b = 6 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0445 \u0442\u0435\u0441\u0442\u043e\u0432; \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 \u0425\u043e\u043b\u043c\u0430\u2013\u0411\u043e\u043d\u0444\u0435\u0440\u0440\u043e\u043d\u0438 \u043f\u0440\u0438 \u03b1=0.05; \u043e\u0442\u0447\u0451\u0442 \u0441\u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 p.\n\u041c\u0435\u0445\u0430\u043d\u0438\u0437\u043c: \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0447\u0438\u0441\u043b\u0430 \u0432\u044b\u0437\u043e\u0432\u043e\u0432, \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0445 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 (\u043c\u0435\u0434\u0438\u0430\u043d\u0430/CI, \u043f\u0430\u0440\u043d\u044b\u0435 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f) \u0438 \u0442\u043e\u043a\u0435\u043d\u043e\u0432/\u0441\u0435\u043a \u043c\u0435\u0436\u0434\u0443 \u043c\u0435\u0442\u043e\u0434\u0430\u043c\u0438; \u0442\u0430\u0431\u043b\u0438\u0446\u0430 per-stage breakdown \u0434\u043b\u044f BoT (latency \u0438 \u0434\u043e\u043b\u044f \u043e\u0442 \u043e\u0431\u0449\u0435\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438) \u0438 \u0434\u043b\u044f PAL (\u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f vs exec). \u0410\u0442\u0440\u0438\u0431\u0443\u0446\u0438\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u044b \u043d\u0430 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u044b (\u043f.2).\n\u0427\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c: \u043f\u0435\u0440\u0435\u0441\u0447\u0451\u0442 \u043f\u0440\u0438 N=3; \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u043d\u0438\u0435 \u0432\u0435\u0440\u0445\u043d\u0438\u0445/\u043d\u0438\u0436\u043d\u0438\u0445 5% \u0432\u044b\u0431\u0440\u043e\u0441\u043e\u0432; per-problem \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u0432\u043c\u0435\u0441\u0442\u043e \u043c\u0435\u0434\u0438\u0430\u043d\u044b; \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439 \u043c\u0435\u0436\u0434\u0443 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430\u043c\u0438; \u043f\u0440\u0438 API \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u00ab\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0437\u0430\u043f\u0440\u043e\u0441 N \u0440\u0430\u0437\u00bb \u0434\u043b\u044f \u043e\u0446\u0435\u043d\u043a\u0438 \u0434\u0438\u0441\u043f\u0435\u0440\u0441\u0438\u0438 \u0441\u0435\u0442\u0438.\n\n## 8. Feasibility\n\u0422\u0435\u043a\u0443\u0449\u0435\u0435 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0435 (sandbox): GPU-\u0434\u0440\u0430\u0439\u0432\u0435\u0440\u0430 \u043d\u0435\u0442 (nvidia-smi \u043d\u0435 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442), \u0441\u0435\u0442\u044c \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u0430 (\u043a\u043e\u043d\u0442\u0435\u043d\u0442 \u043d\u0435 \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d), ML/API-\u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0438 \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b (torch/transformers/openai/faiss/datasets \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442), \u0435\u0441\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0439 Python 3.14, 224 CPU, ~2 TB RAM. \u0421\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u0432 \u044d\u0442\u043e\u043c \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u0424\u0418\u0417\u0418\u0427\u0415\u0421\u041a\u0418 \u041d\u0415 \u0417\u0410\u041f\u0423\u0421\u041a\u0410\u0415\u0422\u0421\u042f \u2014 \u044d\u0442\u043e \u0447\u0438\u0441\u0442\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u043d\u044b\u0439 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b.\n\u0422\u0440\u0435\u0431\u0443\u0435\u043c\u0430\u044f \u0441\u0440\u0435\u0434\u0430 \u0434\u043b\u044f \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430:\n- \u0411\u044d\u043a\u0435\u043d\u0434: \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e \u0440\u0430\u0437\u0432\u0451\u0440\u043d\u0443\u0442\u0430\u044f \u043e\u0442\u043a\u0440\u044b\u0442\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c 70B-\u043a\u043b\u0430\u0441\u0441\u0430 (Llama-2/3-70B, Qwen2-72B, Mixtral \u0438 \u0442.\u043f.) \u2014 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u0441\u0442\u0430\u0442\u044c\u0438 (GPT-4-\u043a\u043b\u0430\u0441\u0441), \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0439 \u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441 \u043f\u0440\u0435\u0434\u043f\u043e\u0447\u0442\u0438\u0442\u0435\u043b\u0435\u043d \u0440\u0430\u0434\u0438 \u0447\u0438\u0441\u0442\u043e\u0442\u044b \u0437\u0430\u043c\u0435\u0440\u043e\u0432; fallback \u2014 API GPT-4-\u043a\u043b\u0430\u0441\u0441\u0430 \u0441 \u044f\u0432\u043d\u043e\u0439 \u043e\u0433\u043e\u0432\u043e\u0440\u043a\u043e\u0439 \u043f\u0440\u043e \u0441\u0435\u0442\u0435\u0432\u043e\u0439 \u0448\u0443\u043c \u0438 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u043c TTFT-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u043c.\n- \u0416\u0435\u043b\u0435\u0437\u043e: \u22652\u00d7A100/H100-80GB \u0434\u043b\u044f 70B (\u0438\u043b\u0438 \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442); CPU-\u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441 \u043d\u0435\u0446\u0435\u043b\u0435\u0441\u043e\u043e\u0431\u0440\u0430\u0437\u0435\u043d.\n- \u041f\u041e: PyTorch + vLLM/SGLang (\u0438\u043b\u0438 \u0430\u043d\u0430\u043b\u043e\u0433), \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433-\u043c\u043e\u0434\u0435\u043b\u044c \u0434\u043b\u044f retrieval (\u043d\u0430\u043f\u0440. text-embedding-ada-002/BGE-large), Python-\u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0430 \u0434\u043b\u044f exec, \u0442\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0442\u043e\u0440 \u0434\u043b\u044f \u043f\u043e\u0434\u0441\u0447\u0451\u0442\u0430 \u0442\u043e\u043a\u0435\u043d\u043e\u0432.\n- \u0414\u0430\u043d\u043d\u044b\u0435: \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u044b Game of 24 (1 364), MGSM (HF, 250/\u044f\u0437\u044b\u043a), Checkmate-in-One (~1 105) + \u043f\u0440\u043e\u043c\u043f\u0442\u044b/\u0448\u0430\u0431\u043b\u043e\u043d\u044b/\u0431\u0443\u0444\u0435\u0440 \u0438\u0437 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f BoT.\n- \u0412\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u043e \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044e BoT: \u0447\u0438\u0441\u043b\u043e LLM-\u0432\u044b\u0437\u043e\u0432\u043e\u0432 \u043d\u0430 \u0437\u0430\u043f\u0440\u043e\u0441, \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c router'\u0430, k retrieval \u0438 \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433-\u043c\u043e\u0434\u0435\u043b\u044c, \u043a\u043e\u0433\u0434\u0430 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u043a\u043e\u0434\u0438\u043d\u0433-\u043f\u0443\u0442\u044c \u0438 exec, \u0440\u0430\u0437\u043c\u0435\u0440\u044b/\u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432, \u0442\u043e\u0447\u043d\u044b\u0435 \u043f\u0440\u043e\u043c\u043f\u0442\u044b; \u0441\u0432\u0435\u0440\u0438\u0442\u044c \u043d\u0430\u0448 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u0441 \u0442\u0440\u0430\u0441\u0441\u043e\u0439 \u0440\u0435\u043f\u043e \u043d\u0430 3\u20135 \u043f\u0440\u0438\u043c\u0435\u0440\u0430\u0445.\n- \u041e\u0431\u044a\u0451\u043c/\u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c: ~70\u201375 \u0442\u044b\u0441. LLM-\u0432\u044b\u0437\u043e\u0432\u043e\u0432, ~90\u2013110 \u043c\u043b\u043d \u0442\u043e\u043a\u0435\u043d\u043e\u0432 (\u043e\u0446\u0435\u043d\u043a\u0430); \u043f\u0440\u0438 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e\u043c inference \u2014 GPU-\u0447\u0430\u0441\u044b \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u0434\u0435\u0441\u044f\u0442\u043a\u043e\u0432\u2013\u0441\u043e\u0442\u0435\u043d \u043d\u0430 2\u00d7H100 \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u0438; \u043f\u0440\u0438 API \u2014 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u043f\u043e\u0440\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0430 \u0442\u043e\u043a\u0435\u043d\u0430\u043c (\u043f\u043e\u0440\u044f\u0434\u043e\u043a \u043e\u0446\u0435\u043d\u0438\u0442\u044c \u043f\u043e \u0442\u0430\u0440\u0438\u0444\u0443 \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0432\u0430\u0439\u0434\u0435\u0440\u0430). \u0411\u044e\u0434\u0436\u0435\u0442 \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u043c S \u0438 N.\n\n## 9. \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438 (\u043a\u0430\u0436\u0434\u044b\u0439 \u043f\u0443\u043d\u043a\u0442 \u043f\u043e\u043c\u0435\u0447\u0435\u043d)\n\u0418\u0437 \u0422\u0417 (\u0434\u0430\u043d\u043e, \u043d\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u0442\u0441\u044f): Expert \u0438 PAL \u2014 single-query; BoT \u2014 retrieval-augmented, \u0448\u0430\u0431\u043b\u043e\u043d\u043d\u043e-\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0439.\n\u0418\u0437 \u043f\u0430\u043c\u044f\u0442\u0438 \u043e \u0441\u0442\u0430\u0442\u044c\u0435 (\u041f\u0420\u0418\u041d\u042f\u0422\u041e \u0420\u0410\u0411\u041e\u0427\u0415, \u043a \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438/\u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430\u0445 \u043f\u0435\u0440\u0435\u0434 \u0437\u0430\u043f\u0443\u0441\u043a\u043e\u043c): BoT = 3 \u0433\u0435\u043d-\u0432\u044b\u0437\u043e\u0432\u0430 + retrieval; \u0440\u0430\u0437\u043c\u0435\u0440\u044b \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432 Game of 24 1 364 / MGSM 250\u00d7\u044f\u0437\u044b\u043a / Checkmate \u22481 105; \u043d\u0430\u043b\u0438\u0447\u0438\u0435 \u0438 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c router'\u0430; \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433-\u043c\u043e\u0434\u0435\u043b\u044c retrieval; \u043d\u0430\u0431\u043e\u0440 \u044f\u0437\u044b\u043a\u043e\u0432 MGSM \u0432 \u0441\u0442\u0430\u0442\u044c\u0435.\n\u042f\u0432\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u0441\u0430\u043c\u0438): \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u0435 \u0431\u0443\u0444\u0435\u0440\u0430 \u2014 \u0432\u043d\u0435 per-query (\u043e\u0434\u043d\u043e\u0440\u0430\u0437\u043e\u0432\u043e, \u043e\u0442\u0447\u0451\u0442 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e); retrieval \u0438 exec \u2014 \u0432\u043d\u0443\u0442\u0440\u0438 end-to-end; \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0437\u0430\u043c\u0435\u0440 \u043f\u0440\u0438 temperature=0; N=5 \u043f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u0438\u0439; \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438 S \u0434\u043b\u044f timing (500/1 000/500) \u0438 \u043f\u043e\u043b\u043d\u044b\u0435 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u044b \u0434\u043b\u044f accuracy; \u00abinference time\u00bb = \u0441\u0442\u0435\u043d\u043d\u044b\u0435 \u0447\u0430\u0441\u044b \u0434\u043e \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043e\u0442\u0432\u0435\u0442\u0430, \u0442\u043e\u043a\u0435\u043d\u044b \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u044e\u0449\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430; \u043f\u0440\u0438 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e\u043c \u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441\u0435 \u0441\u0435\u0442\u044c \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0438\u0437 \u0430\u043d\u0430\u043b\u0438\u0437\u0430, \u043f\u0440\u0438 API \u2014 \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043c\u0435\u0434\u0438\u0430\u043d\u0430\u043c\u0438 \u0438 TTFT-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u043c.\n\n\u0413\u0438\u043f\u043e\u0442\u0435\u0437\u0430 (\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439 \u0432\u044b\u0432\u043e\u0434 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430, \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0437\u0430\u043f\u0443\u0441\u043a\u0430): BoT \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u0442 per-query wall-clock inference time \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e Expert \u0438 PAL \u043d\u0430 \u0432\u0441\u0435\u0445 \u0442\u0440\u0451\u0445 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430\u0445, \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u0437\u0430 \u0441\u0447\u0451\u0442 \u0431\u043e\u043b\u044c\u0448\u0435\u0433\u043e \u0447\u0438\u0441\u043b\u0430 LLM-\u0432\u044b\u0437\u043e\u0432\u043e\u0432 (3 vs 1) \u0438 \u0431\u043e\u043b\u044c\u0448\u0435\u0433\u043e \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e\u0433\u043e \u0447\u0438\u0441\u043b\u0430 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 (distillation + instance reasoning + router) \u043f\u043b\u044e\u0441 retrieval; \u0434\u0438\u0437\u0430\u0439\u043d \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u043e\u0446\u0435\u043d\u0438\u0442\u044c \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u0443 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u0441 CI \u0438 \u0430\u0442\u0440\u0438\u0431\u0443\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0440\u0430\u0437\u043d\u0438\u0446\u044b.", "evidence": "\u0418\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f \u0441\u0440\u0435\u0434\u044b (\u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0430 \u0432 \u043f\u043b\u0430\u043d\u0435): /workspace \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json (518 \u0431\u0430\u0439\u0442); \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 track.md \u043e\u043f\u0438\u0441\u0430\u043d \u043a\u0430\u043a \u00abDesign-only task; repositories and compute are not required\u00bb. find \u043f\u043e \u0444\u0430\u0439\u043b\u043e\u0432\u043e\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u0435 \u043d\u0435 \u043d\u0430\u0448\u0451\u043b PDF-\u043e\u0432 \u0441\u0442\u0430\u0442\u044c\u0438, \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432, \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u0432 \u0438\u043b\u0438 \u043a\u043e\u0434\u0430 \u0430\u0432\u0442\u043e\u0440\u043e\u0432. python3 3.14.4; import torch/transformers/openai/faiss/sklearn/datasets/tiktoken/tenacity/vllm/litellm \u2014 \u0432\u0441\u0435 MISSING; nvidia-smi \u043d\u0435 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442; curl \u0432\u043d\u0435\u0448\u043d\u0435\u0433\u043e \u043a\u043e\u043d\u0442\u0435\u043d\u0442\u0430 \u043d\u0435 \u0432\u0435\u0440\u043d\u0443\u043b (\u0441\u0435\u0442\u044c \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u0430); \u0435\u0441\u0442\u044c 224 CPU \u0438 ~2 TB RAM. \u0412\u044b\u0432\u043e\u0434: \u043f\u0435\u0440\u0432\u043e\u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u043f\u043e BoT/Expert/PAL/\u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430\u043c \u0432 workspace \u041d\u0415\u0422, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0432\u0441\u0435 \u0434\u0435\u0442\u0430\u043b\u0438 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 \u0438 \u0440\u0430\u0437\u043c\u0435\u0440\u044b \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432 \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u044b \u043a\u0430\u043a \u00ab\u043f\u0430\u043c\u044f\u0442\u044c \u043e \u0441\u0442\u0430\u0442\u044c\u0435/\u043a \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u043f\u043e \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u043c\u0443 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044e BoT \u0438 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430\u043c\u00bb, \u0430 \u0440\u0430\u043c\u043a\u0438 Expert/PAL single-query \u0438 BoT retrieval-augmented \u0432\u0437\u044f\u0442\u044b \u0438\u0437 \u0422\u0417 \u043a\u0430\u043a \u0434\u0430\u043d\u043d\u043e\u0441\u0442\u044c. \u0420\u0430\u0431\u043e\u0447\u0438\u0435 \u0447\u0438\u0441\u043b\u0430 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u043e\u0432 \u0438 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u044b BoT/Expert/PAL \u2014 \u044d\u0442\u043e \u0440\u0435\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f \u043f\u043e \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u0441\u0442\u0430\u0442\u044c\u0435 (NeurIPS 2024, Buffer of Thoughts), \u0447\u0442\u043e \u044f\u0432\u043d\u043e \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u043e \u0432 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f\u0445 \u0434\u0438\u0437\u0430\u0439\u043d\u0430.", "assumptions": ["\u0418\u0437 \u0422\u0417 (\u0434\u0430\u043d\u043e): Expert \u0438 PAL \u2014 \u043e\u0434\u0438\u043d\u043e\u0447\u043d\u044b\u0435 \u0437\u0430\u043f\u0440\u043e\u0441\u044b (single-query); BoT \u2014 retrieval-augmented, \u0448\u0430\u0431\u043b\u043e\u043d\u043d\u043e-\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0439 reasoning.", "\u0418\u0437 \u043f\u0430\u043c\u044f\u0442\u0438 \u043e \u0441\u0442\u0430\u0442\u044c\u0435 (\u043a \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u0432 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u043c \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 BoT): BoT = 3 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0445 LLM-\u0432\u044b\u0437\u043e\u0432\u0430 (distillation, instance reasoning, router) + 1 \u043d\u0435\u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u044d\u043c\u0431\u0435\u0434\u0434\u0438\u043d\u0433-retrieval; \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u0435/\u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u043c\u0435\u0442\u0430-\u0431\u0443\u0444\u0435\u0440\u0430 \u2014 \u043e\u0434\u043d\u043e\u0440\u0430\u0437\u043e\u0432\u0430\u044f \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u0430\u044f \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c, \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0438\u0437 per-query.", "\u0420\u0430\u0431\u043e\u0447\u0438\u0435 \u0440\u0430\u0437\u043c\u0435\u0440\u044b \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432: Game of 24 1 364; MGSM 250/\u044f\u0437\u044b\u043a (\u0432\u044b\u0431\u0440\u0430\u043d\u044b en/zh/es/fr/de \u0434\u043b\u044f \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0447\u0430\u0441\u0442\u0438, \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 \u0434\u043e 10 \u044f\u0437\u044b\u043a\u043e\u0432 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e); Checkmate-in-One ~1 105 \u2014 \u043a \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u043f\u043e \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u043c \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430\u043c.", "Timing-\u0442\u0440\u0435\u043a: \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 N=5 \u043f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u0438\u0439 \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443 (\u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u0438 N=3), \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438 S=500 (Game of 24)/1 000 (MGSM, \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u043f\u043e \u044f\u0437\u044b\u043a\u0430\u043c)/500 (Checkmate); accuracy-\u0442\u0440\u0435\u043a \u043d\u0430 \u043f\u043e\u043b\u043d\u044b\u0445 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430\u0445, \u043e\u0434\u0438\u043d \u043f\u0440\u043e\u0445\u043e\u0434 temperature=0.", "\u041e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0437\u0430\u043c\u0435\u0440 \u043f\u0440\u0438 temperature=0 (greedy), \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 seed, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u043d\u0435\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u044e\u0449\u0438\u0439 max_tokens, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0441\u044b\u0440\u043e\u0439 \u0442\u0435\u043a\u0441\u0442 \u0437\u0430\u0434\u0430\u0447\u0438 \u0443 \u0432\u0441\u0435\u0445 \u043c\u0435\u0442\u043e\u0434\u043e\u0432.", "'Inference time' = end-to-end wall-clock \u0441\u0442\u0435\u043d\u043d\u044b\u0435 \u0447\u0430\u0441\u044b \u0434\u043e \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043e\u0442\u0432\u0435\u0442\u0430; retrieval \u0438 \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043a\u043e\u0434\u0430 \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u0432 end-to-end (retrieval \u2014 \